/**
 *  Read model of a remote task, issue or subtask. Options are always emitted
 *  (null when absent) so the wire shape stays stable for specta.
 */
export type Task = {
	id: TaskId,
	projectId: RemoteProjectId,
	groupId: TaskGroupId | null,
	parentId: TaskId | null,
	title: string,
	description: string | null,
	status: TaskStatus,
	rawStatus: string,
	priority: TaskPriority,
	rawPriority: string | null,
	assignees: Person[],
	labels: Label[],
	/**  Always `YYYY-MM-DD`. */
	dueDate: string | null,
	url: string,
	/**  RFC 3339 as received from the provider. */
	updatedAt: string | null,
};

/**
 *  Read model of a remote grouping of tasks (for example a task list). Options
 *  are always emitted (null when absent) so the wire shape stays stable.
 */
export type TaskGroup = {
	id: TaskGroupId,
	projectId: RemoteProjectId,
	name: string,
	description: string | null,
	kind: TaskGroupKind,
	position: number | null,
	url: string | null,
};

export type TaskGroupId = string;

/**
 *  Kinds of task group. `Epic`, `Sprint` and `Milestone` are added only
 *  together with the adapters that produce them.
 */
export type TaskGroupKind = "taskList";

export type TaskId = string;

export type TaskPriority = "none" | "low" | "medium" | "high" | "urgent" | "unknown";

export type TaskStatus = "todo" | "inProgress" | "done" | "cancelled" | "unknown";

/**
 *  A task to assign the current user to, on the wire. The connection and task
 *  ids identify a pending task card the frontend created a context from.
 */
export type TaskToAssignInput = {
	connectionId: string,
	taskId: string,
};

export type UnreadableProjectView = {
	tag: string,
	reason: string,
};

/**
 *  A failed Work Tracking command on the wire. `message` is a fixed English
 *  sentence per kind and never holds provider or credential data. Every field
 *  is emitted (null when absent) so the frontend reads one stable shape.
 */
export type WorkTrackingCommandError = {
	kind: WorkTrackingErrorKind,
	message: string,
	field: WorkTrackingField | null,
	reason: WorkTrackingInvalidReason | null,
	retryAfterSeconds: number | null,
	status: number | null,
};

/**  The kind of a failed Work Tracking command, on the wire. */
export type WorkTrackingErrorKind = "notConfigured" | "invalidInput" | "unauthorized" | "forbidden" | "notFound" | "rateLimited" | "timeout" | "network" | "providerError" | "invalidResponse" | "storageError";

/**  The input that failed validation, on the wire. Mirrors [`InputField`]. */
export type WorkTrackingField = "providerKind" | "baseUrl" | "apiKey" | "displayName" | "connectionId" | "projectId" | "groupId" | "itemId" | "cursor" | "pageSize";

/**  Why an input failed validation, on the wire. Mirrors [`InvalidInputReason`]. */
export type WorkTrackingInvalidReason = "required" | "tooLong" | "invalidFormat" | "httpsRequired" | "unsupportedComponent" | "outOfRange" | "unsupported";

/**
 *  A failed workspace command on the wire. `message` is readable and may name
 *  the user's own projects, contexts, repositories and branches.
 */
export type WorkspaceCommandError = {
	kind: WorkspaceErrorKind,
	message: string,
};

/**
 *  A failed workspace-detection command on the wire. `message` is a readable
 *  sentence that may name a path on the user's own machine.
 */
export type WorkspaceDetectorCommandError = {
	kind: WorkspaceDetectorErrorKind,
	message: string,
};

/**  The kind of a workspace-detection failure, as the frontend sees it. */
export type WorkspaceDetectorErrorKind = 
/**  The home directory could not be determined. */
"homeNotFound" | 
/**  The IDE's storage file does not exist yet. */
"storageNotFound" | 
/**  The storage file could not be read. */
"storageUnreadable" | 
/**  The storage file could not be parsed. */
"storageInvalid";

/**
 *  The kind of a workspace failure, as the frontend sees it. `invalidInput`
 *  is a blank or malformed name, id, branch name or prefix; `internal` is a
 *  command's background task failing unexpectedly.
 */
export type WorkspaceErrorKind = "projectNotFound" | "projectAlreadyExists" | "invalidInput" | "duplicateContextName" | "duplicateContextFolder" | "unknownContext" | "unknownRepository" | "defaultContextIsFixed" | "staticContextStatusLocked" | "linkedRepositoryIsReadOnly" | "branchAlreadyExists" | "branchCheckedOut" | "git" | "files" | "storage" | 
/**
 *  The agent tool is unknown, the prompt empty, or the run could not be
 *  started or stopped.
 */
"agentRun" | 
/**  No agent is running for the context, so there is none to stop. */
"noRunningAgent" | "internal";

export type WorktreeStatusView = {
	filesAdded: number,
	filesModified: number,
	filesDeleted: number,
	filesRenamed: number,
	insertions: number,
	deletions: number,
};

export type WorktreeView = {
	name: string,
	path: string,
	branch: string | null,
	isDefault: boolean,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

